    bestm = (0, 0)
    bestscore = None
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not inside(nx, ny) or (nx, ny) in obstacles:
            continue
        dist = (nx - tx) * (nx - tx) + (ny - ty) * (ny - ty)
        # small bias to keep away from opponent unless targeting opponent
        away = (nx - ox) * (nx - ox) + (ny - oy) * (ny - oy) if (tx, ty) != (ox, oy) else 0
